class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        res = 0
        for i in range(n):
            cnt = [0] * 26
            mx = 0
            for j in range(i, n):
                c = ord(s[j]) - 97
                cnt[c] += 1
                if cnt[c] > mx:
                    mx = cnt[c]
                if mx >= k:
                    res += 1
        return res

