        n = len(s)
        cnt = [0] * 26
        left = 0
        bad = 0
        for ch in s:
            cnt[ord(ch) - 97] += 1
            while max(cnt) >= k:
                cnt[ord(s[left]) - 97] -= 1
                left += 1
            bad += left
        return n * (n + 1) // 2 - bad

