class Solution {
    public int numberOfSubstrings(String s, int k) {
        int n = s.length();
        int[] cnt = new int[26];
        long left = 0, bad = 0;
        for (char ch : s.toCharArray()) {
            cnt[ch - 'a']++;
            while (max(cnt) >= k) {
                cnt[s.charAt((int) left) - 'a']--;
                left++;
            }
            bad += left;
        }
        return (int) (1L * n * (n + 1) / 2 - bad);
    }
    private int max(int[] a) {
        int m = 0;
        for (int v : a) m = Math.max(m, v);
        return m;
    }
}

