var numberOfSubstrings = function(s, k) {
    const n = s.length;
    const cnt = new Array(26).fill(0);
    let left = 0, bad = 0;
    for (const ch of s) {
        cnt[ch.charCodeAt(0) - 97]++;
        while (Math.max(...cnt) >= k) {
            cnt[s.charCodeAt(left) - 97]--;
            left++;
        }
        bad += left;
    }
    return n * (n + 1) / 2 - bad;
};
